def connect_markers(grid, bg=0):
    """Connect same-colored marker regions that sit at the corners of a rectangle: draw the rectangle's sides in the marker color, but only over background cells. The frame color (most common nonzero) and background are ignored."""
    from collections import Counter, defaultdict
    from collections import deque
    h, w = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    mx = max(n for c, n in cnt.items() if c != bg)
    frame = {c for c, n in cnt.items() if c != bg and n == mx}
    seen = [[False] * w for _ in range(h)]
    boxes = defaultdict(list)

    def comp(si, sj):
        v = grid[si][sj]
        q = deque([(si, sj)]); seen[si][sj] = True
        cells = []
        while q:
            i, j = q.popleft(); cells.append((i, j))
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < h and 0 <= nj < w and not seen[ni][nj] and grid[ni][nj] == v:
